async function speakGerman(text:string){
  if(!text||typeof window==='undefined')return false;
  const api=(window as Window&{OttoSpeech?:{play?:(value:string,options?:{mode?:'normal'|'slow'})=>Promise<boolean>}}).OttoSpeech;
  if(api?.play)return await api.play(text,{mode:'normal'});
  if(!('speechSynthesis' in window))return false;
  window.speechSynthesis.cancel();
  const utterance=new SpeechSynthesisUtterance(text);utterance.lang='de-DE';utterance.rate=.82;window.speechSynthesis.speak(utterance);return true;
}
function GermanAudioButton({text}:{text:string}){
  const[busy,setBusy]=useState(false);
  const play=async()=>{setBusy(true);try{await speakGerman(text)}finally{setBusy(false)}};
  return <button type="button" onClick={play} aria-busy={busy} className={"ml-2 inline-grid h-8 w-8 shrink-0 place-items-center rounded-lg border bg-white text-teal-800 align-middle transition "+(busy?'scale-95 bg-teal-50 ring-2 ring-teal-200':'')} aria-label={"Озвучить "+text} title={"Озвучить: "+text}><Volume2 className={"h-3.5 w-3.5"+(busy?' animate-pulse':'')}/></button>
}

function SourceVisual({visual}:{visual:keyof typeof VISUALS}){
  const[zoom,setZoom]=useState(false);
  const v=VISUALS[visual];
  const[broken,setBroken]=useState(false);
  const image=broken
    ?<div role="status" className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950">Оригинальное изображение сейчас недоступно. Для восстановления требуется исходный файл.</div>
    :<img src={v.src} alt={v.alt} draggable={false} onError={()=>setBroken(true)} className="mx-auto block h-auto max-h-[720px] w-auto max-w-full select-none rounded-xl object-contain"/>;
  return <div className="my-4 mx-auto w-full max-w-3xl rounded-2xl border border-slate-200 bg-white p-2 shadow-sm">
    <button type="button" disabled={broken} className="block w-full text-center disabled:cursor-default" onClick={()=>setZoom(true)} aria-label={v.alt+" — увеличить"}>{image}<span className="mt-2 block text-center text-xs font-bold text-teal-800">Нажмите, чтобы увеличить</span></button>
    {zoom&&<div className="fixed inset-0 z-[210] grid place-items-center bg-slate-950/85 p-3" onClick={()=>setZoom(false)}><div className="relative max-h-[94vh] w-full max-w-5xl overflow-auto rounded-2xl bg-white p-3" onClick={e=>e.stopPropagation()}><button type="button" onClick={()=>setZoom(false)} className="sticky left-full top-0 z-10 grid h-10 w-10 place-items-center rounded-xl border bg-white" aria-label="Закрыть"><X className="h-5 w-5"/></button>{image}</div></div>}
  </div>;
}

const ALL=[...EXAM_REFERENCE_DATA.written,...EXAM_REFERENCE_DATA.oral];
const BY_ID=new Map(ALL.map(item=>[item.id,item]));

function SmartButton({id,saved,onToggle}:{id:string;saved:boolean;onToggle:(id:string)=>void}){
  const[status,setStatus]=useState('');
  const click=()=>{
    if(saved){setStatus('Уже добавлено в умные карточки');window.setTimeout(()=>setStatus(''),1800);return}
    onToggle(id);setStatus('Добавлено в умные карточки');window.setTimeout(()=>setStatus(''),1800);
  };
  const label=saved?'Уже добавлено в умные карточки':'Добавить в умные карточки';
  return <span className="relative shrink-0"><button type="button" onClick={click} className={"inline-flex min-h-10 items-center gap-2 rounded-xl border px-3 py-2 text-left text-xs font-black leading-4 transition sm:text-sm "+(saved?'border-teal-300 bg-teal-50 text-teal-900':'border-slate-200 bg-white text-slate-700 hover:border-teal-300 hover:text-teal-800')} aria-label={label} title={label}>{saved?<BookmarkCheck className="h-4 w-4 shrink-0"/>:<Bookmark className="h-4 w-4 shrink-0"/>}<span className="max-w-[150px] sm:max-w-none">{saved?'✓ Уже добавлено в умные карточки':'Добавить в умные карточки'}</span></button>{status&&<span role="status" className="absolute right-0 top-[calc(100%+6px)] z-20 w-max max-w-[240px] rounded-lg border bg-white px-3 py-2 text-xs font-bold text-slate-700 shadow-lg">{status}</span>}</span>;
}
function normalizeSourcePart(part:string){
  return part.split('\n').map(line=>line.trim()).filter(Boolean).join(' ').replace(/\s+/g,' ').trim();
}
function isGermanOnly(text:string){return /[A-Za-zÄÖÜäöüß]/.test(text)&&!/[А-Яа-яЁё]/.test(text)}
function isRussianLed(text:string){return /^[^A-Za-zÄÖÜäöüß]*[А-Яа-яЁё]/.test(text)}
function pickAudioUnit(sectionId:string,text:string){
  if(sectionId==='written_intro'||sectionId==='oral_intro')return null;
  const units=EXAM_AUDIO[sectionId]||[];
  const candidates=units.filter(unit=>text.includes(unit.match)).sort((a,b)=>b.match.length-a.match.length);
  return candidates[0]||null;
}
function splitLearningPair(text:string){
  const dialogue=text.match(/^(Mann|Frau):\s*(.+)$/);
  if(dialogue){
    const firstRu=dialogue[2].search(/[А-Яа-яЁё]/);
    if(firstRu>0)return{speaker:dialogue[1],de:dialogue[2].slice(0,firstRu).trim(),ru:dialogue[2].slice(firstRu).trim()};
    return{speaker:dialogue[1],de:dialogue[2].trim(),ru:''};
  }
  const dash=text.match(/^(.+?)\s+-\s+([А-ЯЁ].+)$/);
  if(dash&&/[A-Za-zÄÖÜäöüß]/.test(dash[1]))return{de:dash[1].trim(),ru:dash[2].trim()};
  const paren=text.match(/^(.+?[.!?])\s*\(([А-ЯЁ].+)\)$/);
  if(paren&&/[A-Za-zÄÖÜäöüß]/.test(paren[1]))return{de:paren[1].trim(),ru:'('+paren[2].trim()+')'};
  const firstRu=text.search(/[А-Яа-яЁё]/);
  if(firstRu>0){
    const before=text.slice(0,firstRu).trim();
    const after=text.slice(firstRu).trim();
    if(/[.!?]$/.test(before)&&/[A-Za-zÄÖÜäöüß]/.test(before))return{de:before,ru:after};
  }
  const note=text.match(/^(.+?\)),?\s*(\((?:обращение|фамилия).+\))$/i);
  if(note)return{de:note[1].trim(),ru:note[2].trim()};
  return null;
}
function SprechenTeil1QaTable({lines}:{lines:string[]}){
  const rows=lines.map(line=>line.match(/^(Name\?|Alter\?|Land\?|Wohnort\?|Sprachen\?|Beruf\?|Hobby\?)\s+(.+)$/)).filter((m):m is RegExpMatchArray=>Boolean(m));
  if(!rows.length)return null;
  return <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white">
    <div className="hidden grid-cols-[170px_1fr] border-b bg-teal-50 px-4 py-3 text-sm font-black text-slate-800 sm:grid"><span>Вопрос</span><span>Пример ответа</span></div>
    <div className="divide-y">{rows.map(row=><div key={row[1]} className="grid gap-3 p-4 sm:grid-cols-[170px_1fr] sm:gap-5">
      <div className="flex items-start justify-between gap-2"><b className="text-slate-950">{row[1]}</b><GermanAudioButton text={row[1]}/></div>
      <div className="flex items-start justify-between gap-2"><span className="font-semibold leading-6 text-slate-900">{row[2]}</span><GermanAudioButton text={row[2]}/></div>
    </div>)}</div>
  </div>;
}
function LearningPair({speaker,de,ru,audio}:{speaker?:string;de:string;ru:string;audio?:string}){
  return <div className="rounded-xl border border-slate-200 bg-white px-4 py-3">
    {speaker&&<div className="mb-1 text-xs font-black uppercase tracking-wide text-teal-800">{speaker}:</div>}
    <div className="flex items-start gap-3"><div className="min-w-0 flex-1 text-[15px] font-semibold leading-7 text-slate-950">{de}</div>{audio&&<GermanAudioButton text={audio}/>}</div>
    {ru&&<div className="mt-1 text-sm font-medium leading-6 text-slate-700">{ru}</div>}
  </div>;
}
function SourceBody({sectionId,body}:{sectionId:string;body:string}){
  const rawParts=body.split(/\n\s*\n/g).map(v=>v.trim()).filter(Boolean);
  const visuals=VISUAL_PLACEMENTS[sectionId]||[];
  const audioUnits=sectionId==='written_intro'||sectionId==='oral_intro'||sectionId==='oral_teil1'?[]:(EXAM_AUDIO[sectionId]||[]);
  const rendered:ReactNode[]=[];
  const pairedTranslationStarts:Record<string,string[]>={written_horen_2:['Guten Tag! Liebe Kunden,'],written_horen_3:['Guten Abend, Herr Doktor Schulz.']};

  const unitForLine=(line:string)=>{
    const probe=line.replace(/^(?:[•abc]|\d+)\s+/,'').trim();
    return audioUnits.filter(unit=>probe.startsWith(unit.match)).sort((a,b)=>b.match.length-a.match.length)[0]||null;
  };
  const segmentPart=(part:string)=>{
    const lines=part.split('\n').map(line=>line.trim()).filter(Boolean);
    const segments:{kind:'learning'|'plain';text:string;audio?:string}[]=[];
    let current:{kind:'learning'|'plain';text:string;audio?:string}|null=null;
    const flush=()=>{if(current?.text.trim())segments.push({...current,text:current.text.trim()});current=null};
    for(const line of lines){
      const unit=unitForLine(line);
      const russianLed=isRussianLed(line);
      if(unit){
        const currentText=current?.text.trim()||'';
        const incompleteLearning=current?.kind==='learning'&&!/[.!?]$/.test(currentText)&&!/^(Liebe|Lieber|Sehr geehrte|Sehr geehrter)/.test(currentText)&&!/^(Richtig|Falsch)$/.test(currentText);
        if(incompleteLearning){current!.text+=' '+line;continue}
        flush();
        current={kind:'learning',text:line,audio:unit.audio};
        continue;
      }
      if(current?.kind==='learning'&&russianLed){if(/[А-Яа-яЁё]/.test(current.text)){current.text+=' '+line;continue}flush();current={kind:'plain',text:line};continue}
      if(current?.kind==='learning'&&/^(Richtig|Falsch)$/.test(current.text.trim())){flush();current={kind:'plain',text:line};continue}
      if(!current)current={kind:'plain',text:line};
      else current.text+=' '+line;
    }
    flush();
    return segments;
  };

  for(let index=0;index<rawParts.length;index+=1){
    const part=rawParts[index];
    const matchingVisuals=visuals.filter(item=>part.includes(item.match));

    if(sectionId==='written_horen_1'&&part.startsWith('Welche Busnummer fährt zum Bahnhof?')){
      // Keep the exact supplied Goethe question, cropped bus illustration and
      // answer options together; preserve the original individual speech buttons.
      const lines=part.split('\n').map(line=>line.trim()).filter(Boolean);
      const choices=lines.slice(1,4).map(line=>{
        const match=/^([abc])\s+(Bus\s+\d+\.)$/.exec(line);
        return match?{letter:match[1],answer:match[2],source:line}:null;
      });
      if(choices.length===3&&choices.every(Boolean)){
        const question=lines[0];
        const explanation=lines.slice(4).join(' ');
        rendered.push(<div key={'part-'+index} className="space-y-3">
          <div className="rounded-2xl border border-slate-200 bg-white p-3">
            <div className="flex items-start justify-between gap-2 px-1">
              <p lang="de" className="min-w-0 text-[15px] font-bold leading-6 text-slate-950">{question}</p>
              <GermanAudioButton text={unitForLine(question)?.audio||question}/>
            </div>
            <SourceVisual visual="w_horen1"/>
            <div className="grid grid-cols-3 gap-2" aria-label="Варианты ответов Hören Teil 1">
              {choices.map(choice=>choice&&<div key={choice.letter} className="flex min-w-0 flex-col items-center gap-2 rounded-lg border border-slate-200 px-1 py-2 text-center">
                <span lang="de" className="text-xs leading-5 text-slate-800 sm:text-sm"><b className="mr-1">{choice.letter}</b>{choice.answer}</span>
                <GermanAudioButton text={unitForLine(choice.source)?.audio||choice.answer}/>
              </div>)}
            </div>
          </div>
          {explanation&&<p className="max-w-none text-[15px] font-medium leading-7 text-slate-700">{explanation}</p>}
        </div>);
        continue;
      }
    }

    if(sectionId==='oral_teil1'){
      const lines=part.split('\n').map(line=>line.trim()).filter(Boolean);
      const qaLines=lines.filter(line=>/^(Name\?|Alter\?|Land\?|Wohnort\?|Sprachen\?|Beruf\?|Hobby\?)\s+/.test(line));
      if(qaLines.length){
        const rest=lines.filter(line=>!qaLines.includes(line));
        rendered.push(<div key={'part-'+index} className="space-y-4"><SprechenTeil1QaTable lines={qaLines}/>{rest.length>0&&<p className="text-sm font-medium leading-7 text-slate-700">{rest.join(' ')}</p>}{matchingVisuals.map(item=><SourceVisual key={item.visual} visual={item.visual}/>)}</div>);
        continue;
      }
      const answerIndex=lines.findIndex(line=>line.startsWith('Ответ: '));
      if(answerIndex>=0){
        const before=lines.slice(0,answerIndex).join(' ').trim();
        const answer=lines[answerIndex].slice('Ответ: '.length).trim();
        const after=lines.slice(answerIndex+1).join(' ').trim();
        rendered.push(<div key={'part-'+index} className="space-y-3">{before&&<p className="text-sm font-medium leading-7 text-slate-700">{before}</p>}<div className="rounded-xl border border-slate-200 bg-white px-4 py-3"><div className="text-xs font-black uppercase tracking-wide text-slate-500">Ответ:</div><div className="mt-1 flex items-start gap-3"><span className="min-w-0 flex-1 font-semibold leading-7 text-slate-950">{answer}</span><GermanAudioButton text={answer}/></div></div>{after&&<p className="text-sm font-medium leading-7 text-slate-700">{after}</p>}{matchingVisuals.map(item=><SourceVisual key={item.visual} visual={item.visual}/>)}</div>);
        continue;
      }
    }

    const normalized=normalizeSourcePart(part);
    const next=index+1<rawParts.length?normalizeSourcePart(rawParts[index+1]):'';
    if((pairedTranslationStarts[sectionId]||[]).some(prefix=>normalized.startsWith(prefix))&&next&&isRussianLed(next)){
      const audio=pickAudioUnit(sectionId,normalized)?.audio||normalized;
      rendered.push(<div key={'part-'+index} className="space-y-3"><LearningPair de={normalized} ru={next} audio={audio}/>{matchingVisuals.map(item=><SourceVisual key={item.visual} visual={item.visual}/>)}</div>);
      index+=1;
      continue;
    }

    const russianHeadedStructured=new Set(['written_greeting','written_templates_greeting','written_templates_farewell','written_farewell']);
    if(isRussianLed(normalized)&&!russianHeadedStructured.has(sectionId)){
      rendered.push(<div key={'part-'+index} className="space-y-3"><p className="max-w-none text-[15px] font-medium leading-7 text-slate-700">{normalized}</p>{matchingVisuals.map(item=><SourceVisual key={item.visual} visual={item.visual}/>)}</div>);
      continue;
    }

    const segments=segmentPart(part);
    rendered.push(<div key={'part-'+index} className="space-y-3">{segments.map((segment,segmentIndex)=>{
      if(segment.kind==='plain')return <p key={segmentIndex} className="max-w-none text-[15px] font-medium leading-7 text-slate-700">{segment.text}</p>;
      const pair=splitLearningPair(segment.text);
      if(pair)return <LearningPair key={segmentIndex} speaker={pair.speaker} de={pair.de} ru={pair.ru} audio={segment.audio||pair.de}/>;
      return <LearningPair key={segmentIndex} de={segment.text} ru="" audio={segment.audio||segment.text}/>;
    })}{matchingVisuals.map(item=><SourceVisual key={item.visual} visual={item.visual}/>)}</div>);
  }

  return <div className="mt-4 space-y-4">{rendered}</div>;
}
export function ExamReferenceSection({kind,saved,onToggle,initialSectionId,embedded=false}:{kind:ExamReferenceKind;saved:Set<string>;onToggle:(id:string)=>void;initialSectionId?:string;embedded?:boolean}){
  const sections=EXAM_REFERENCE_DATA[kind];
  const[openId,setOpenId]=useState<string>(()=>initialSectionId&&sections.some(item=>item.id===initialSectionId)?initialSectionId:sections[0]?.id||'');
  const[detailOpen,setDetailOpen]=useState(Boolean(initialSectionId));
  const sectionRoot=useRef<HTMLDivElement|null>(null);
  useEffect(()=>{
    if(initialSectionId&&sections.some(item=>item.id===initialSectionId)){
      setOpenId(initialSectionId);
      setDetailOpen(true);
    }else{
      setOpenId(sections[0]?.id||'');
      setDetailOpen(false);
    }
  },[initialSectionId,kind]);
  const active=sections.find(item=>item.id===openId)||sections[0];
  const nextTopic=sections[sections.findIndex(item=>item.id===active.id)+1];
  const scrollToTop=()=>{
    // Scope scrolling to this reference view: the underlying training screen
    // can stay mounted behind the overlay and must not receive the scroll.
    const root=sectionRoot.current;
    const scrollport=root?.closest('.otto-reference-overlay')?.querySelector<HTMLElement>('main')
      ??root?.closest<HTMLElement>('.otto-reference-entry-welcome')
      ??root?.closest<HTMLElement>('.otto-inner-screen');
    scrollport?.scrollTo({top:0,behavior:'auto'});
  };
  const scheduleScrollToTop=()=>window.requestAnimationFrame(()=>window.requestAnimationFrame(scrollToTop));
  const openTopic=(id:string)=>{
    setOpenId(id);
    setDetailOpen(true);
    scheduleScrollToTop();
  };
  const backToTopics=()=>{
    setDetailOpen(false);
    scheduleScrollToTop();
  };
  if(embedded)return <section className="rounded-[24px] border border-[var(--otto-line)] bg-white p-4 sm:p-5"><p className="text-xs font-black uppercase tracking-[.14em] text-teal-700">OTTO A1 · Справочник</p><div className="mt-2 flex flex-wrap items-start justify-between gap-3"><h2 className="min-w-0 text-xl font-black text-slate-950">{active.title}</h2>{active.smart&&<SmartButton id={active.id} saved={saved.has(active.id)} onToggle={onToggle}/>}</div><SourceBody sectionId={active.id} body={active.body}/></section>;
  // Exam sections share the same one-column Shell and topic navigation as the A1 base.
  // No independent sidebar or alternate page is mounted.
  return <div ref={sectionRoot} className="otto-reference-exam-content min-w-0 w-full max-w-full">
    {!detailOpen ? <>
      <p className="otto-kicker">OTTO A1 · СПРАВОЧНИК</p>
      <h2 className="otto-reference-section-title mt-2 font-black text-slate-950">{kind==='written'?'Письменная часть экзамена':'Устная часть экзамена'}</h2>
      <div className="mt-5 grid min-w-0 gap-2 sm:grid-cols-2" aria-label={kind==='written'?'Темы письменной части':'Темы устной части'}>
        {sections.map(item=><button key={item.id} type="button" onClick={()=>openTopic(item.id)}
          className="otto-reference-topic-button flex min-h-12 min-w-0 w-full items-center justify-between gap-3 rounded-xl border border-[var(--otto-line)] bg-white px-4 py-3 text-left text-sm font-black text-slate-900 hover:border-teal-300 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-teal-200">
          <span className="min-w-0 break-words">{item.title}</span><ChevronRight className="h-4 w-4 shrink-0 text-teal-700"/>
        </button>)}
      </div>
    </> : <article className="otto-reference-exam-topic min-w-0 max-w-full">
      <p className="otto-kicker">OTTO A1 · СПРАВОЧНИК</p>
      <div className="mt-2 flex flex-wrap items-start justify-between gap-3">
        <h2 className="otto-reference-topic-title min-w-0 font-black text-slate-950">{active.title}</h2>
        {active.smart&&<SmartButton id={active.id} saved={saved.has(active.id)} onToggle={onToggle}/>}
      </div>
      <SourceBody sectionId={active.id} body={active.body}/>
      <nav className="mt-6 grid min-w-0 grid-cols-2 gap-3 border-t border-[var(--otto-line)] pt-4" aria-label="Навигация по темам экзамена">
        <button type="button" onClick={backToTopics} className="min-h-12 min-w-0 rounded-xl border border-[var(--otto-line)] bg-white px-3 text-sm font-bold">Назад к темам</button>
        {nextTopic?<button type="button" onClick={()=>openTopic(nextTopic.id)} className="min-h-12 min-w-0 rounded-xl bg-teal-700 px-3 text-sm font-bold text-white">Далее →</button>:
          <button type="button" onClick={backToTopics} className="min-h-12 min-w-0 rounded-xl bg-teal-700 px-3 text-sm font-bold text-white">Завершить раздел</button>}
      </nav>
    </article>}
  </div>;
}
export function ExamSmartCardsPanel({ids}:{ids:string[]}){
  const items=useMemo(()=>ids.map(id=>BY_ID.get(id)).filter((v):v is ExamSourceSection=>Boolean(v)),[ids]);
  const[open,setOpen]=useState<string|null>(null);
  if(!items.length)return null;
  return <section className="mt-5 rounded-[24px] border border-teal-200 bg-teal-50 p-5 shadow-sm">
    <b className="text-lg text-teal-950">Мои умные карточки</b>
    <p className="mt-2 text-sm leading-6 text-slate-600">Откройте сохранённый блок и используйте само содержание как шпаргалку.</p>
    <div className="mt-3 space-y-2">{items.map(item=><div key={item.id} className="rounded-xl border border-teal-200 bg-white"><button type="button" onClick={()=>setOpen(open===item.id?null:item.id)} className="flex min-h-12 w-full items-center justify-between gap-3 px-4 py-3 text-left text-sm font-black text-slate-900"><span>{item.title}</span><ChevronDown className={"h-4 w-4 transition "+(open===item.id?'rotate-180':'')}/></button>{open===item.id&&<div className="border-t border-teal-100 px-4 pb-4"><SourceBody sectionId={item.id} body={item.body}/></div>}</div>)}</div>
  </section>;
}
export function getExamSmartCardTitle(id:string){return BY_ID.get(id)?.title||null}
